{
  "company": "CRONUS International Ltd.",
  "messageType": "Inventory.Attribute.Create",
  "status": "Success",
  "contract": "json",
  "format": "chapters",
  "catalogue": {
    "name": "Inventory.Attribute.Create",
    "isEnabled": true,
    "filterTableNo": 27,
    "description": "Úthlutar eiginleikagildum á vöru. Breytir engu ef sama gildi er þegar til.",
    "selectionDescription": "Úthlutar eiginleikagildum á vöru og getur búið til valkosti sem vantar; notaðu Inventory.Attribute.Update fyrir núverandi vörutengingu.",
    "messageDirection": "Inbound",
    "keywords": [
      "úthluta eiginleika vöru",
      "búa til eiginleikagildi vöru",
      "stilla eiginleika vöru",
      "merkja vöru",
      "bæta við lýsigögnum vöru"
    ],
    "chargeable": true
  },
  "chapters": {
    "envelope": {
      "subject": {
        "use": "optional",
        "forms": [
          "guid",
          "item no."
        ],
        "description": "The subject identifies the item by number or SystemId; use data item identifiers when subject is omitted."
      },
      "dataRequired": true,
      "version": "1.0",
      "contentType": "text/json"
    },
    "target": [
      {
        "source": "subject",
        "form": "guid",
        "description": "The SystemId of the Item."
      },
      {
        "source": "subject",
        "form": "item no.",
        "description": "The No. of the Item."
      },
      {
        "source": "data.itemNo",
        "form": "item no.",
        "description": "The Item No. to read or change."
      },
      {
        "source": "data.itemId, data.id, data.systemId, data.recordSystemId",
        "form": "guid or item no.",
        "description": "Additional Item identifiers accepted by the resolver."
      },
      {
        "source": "data.tableView",
        "form": "table view",
        "description": "An Item table view used to resolve one or more Items. Inventory.Attribute.Get returns every Item it resolves to; Create and Update write to the first one."
      }
    ],
    "parameters": [
      {
        "name": "attributes",
        "type": "array",
        "required": true,
        "description": "Attribute mapping objects containing name or id, value, and optional type-specific values.",
        "children": [
          {
            "name": "attributeId",
            "type": "integer",
            "required": false,
            "description": "Numeric id of the attribute definition. Tried first when it is not 0; the name is used when no attribute has that id."
          },
          {
            "name": "name",
            "type": "string",
            "required": false,
            "description": "Name of the attribute definition. Send name or attributeId."
          },
          {
            "name": "attributeName",
            "type": "string",
            "required": false,
            "description": "Alias of name; read only when name is empty."
          },
          {
            "name": "type",
            "type": "string",
            "required": false,
            "description": "Optional check: Option, Text, Integer, Decimal or Date. An element whose type differs from the definition is refused; an unrecognised type text is ignored."
          },
          {
            "name": "value",
            "type": "string",
            "required": false,
            "description": "The value as text. Required for Option and Text. For Integer, Decimal and Date it is used when numericValue or dateValue is not sent (decimal point as separator, dates as YYYY-MM-DD)."
          },
          {
            "name": "numericValue",
            "type": "number",
            "required": false,
            "description": "Value of an Integer or Decimal attribute; takes precedence over value."
          },
          {
            "name": "dateValue",
            "type": "string",
            "required": false,
            "description": "Value of a Date attribute in YYYY-MM-DD format; takes precedence over value."
          },
          {
            "name": "createValueIfMissing",
            "type": "boolean",
            "required": false,
            "description": "Create the option value when it does not exist. Default false. Only Option attributes need it; Text, Integer, Decimal and Date values are created when missing."
          },
          {
            "name": "overwrite",
            "type": "boolean",
            "required": false,
            "description": "Replace a different value the item already has for this attribute. Default false: a different value is refused."
          }
        ]
      },
      {
        "name": "allowBlocked",
        "type": "boolean",
        "required": false,
        "description": "Allow writing to a blocked item. Default false."
      }
    ],
    "response": {
      "contentType": "text/json",
      "fields": [
        {
          "name": "status",
          "type": "string",
          "description": "Success when the mappings were written."
        },
        {
          "name": "itemNo",
          "type": "string",
          "description": "The resolved Item No."
        },
        {
          "name": "results",
          "type": "array",
          "description": "The resulting attribute mappings, including changed and value information.",
          "children": [
            {
              "name": "attributeName",
              "type": "string",
              "description": "Attribute name."
            },
            {
              "name": "attributeId",
              "type": "integer",
              "description": "Numeric attribute id."
            },
            {
              "name": "valueId",
              "type": "integer",
              "description": "Id of the value now assigned."
            },
            {
              "name": "value",
              "type": "string",
              "description": "The value now assigned."
            },
            {
              "name": "changed",
              "type": "boolean",
              "description": "False when the item already had this value."
            },
            {
              "name": "before",
              "type": "string",
              "description": "The replaced value; only when overwrite replaced a different value."
            }
          ]
        }
      ]
    },
    "errors": [
      {
        "code": "MissingParameter",
        "when": "No Item identifier in subject or data.",
        "fix": "Send subject or an identifier key under data."
      },
      {
        "code": "RecordNotFound",
        "when": "An identifier was given but matches no Item.",
        "fix": "Check the value or look the record up first."
      },
      {
        "code": "ConflictingIdentifiers",
        "when": "Two identifiers were given that point to different records.",
        "fix": "Send one identifier."
      },
      {
        "code": "InvalidParameterFormat",
        "when": "A SystemId or document identifier cannot be read.",
        "fix": "Send a GUID for SystemId keys and text for document numbers."
      },
      {
        "code": "InvalidLine",
        "when": "Request data.attributes must be a non-empty array.",
        "fix": "Send at least one attribute object."
      },
      {
        "code": "BusinessCentralError",
        "error": "Item \"%1\" already has attribute \"%2\" with a different value.",
        "when": "The item already has a different value and attributes[].overwrite is false.",
        "fix": "Set overwrite to true on the attribute object, or use Inventory.Attribute.Update."
      },
      {
        "code": "BusinessCentralError",
        "error": "Item \"%1\" is blocked. Pass allowBlocked: true to override.",
        "when": "The resolved Item is blocked.",
        "fix": "Set allowBlocked to true only when the write is intentional."
      }
    ],
    "effect": {
      "effect": "write",
      "changes": "Assigns attribute values to one Item. A missing value is created (an Option value only when createValueIfMissing is set) and an existing different value is replaced only when overwrite is set. The Item must not be blocked unless allowBlocked is set.",
      "idempotent": false,
      "permissionSet": "the Bifrost \"Full Access\" permission set",
      "preconditions": [
        "The Attributes domain is turned on in Inventory Setup.",
        "The Item exists and is not blocked, or allowBlocked is true.",
        "Each attribute definition already exists; create it with Inventory.AttributeDefinition.Create."
      ]
    },
    "metering": {
      "chargeable": true,
      "chargedAs": "message"
    },
    "related": [
      {
        "name": "Inventory.Attribute.Update",
        "useInsteadWhen": "Change an existing mapping instead of creating it."
      },
      {
        "name": "Inventory.Attribute.Get",
        "useInsteadWhen": "Read assigned and unassigned values."
      }
    ],
    "examples": [
      {
        "title": "Assign an item attribute",
        "request": {
          "type": "Inventory.Attribute.Create",
          "subject": "1000",
          "data": {
            "attributes": [
              {
                "name": "Finish",
                "value": "Matte",
                "createValueIfMissing": true
              }
            ]
          }
        },
        "response": {
          "status": "Success",
          "itemNo": "1000",
          "results": [
            {
              "attributeName": "Finish",
              "value": "Matte",
              "changed": true,
              "attributeId": 2,
              "valueId": 1
            }
          ]
        }
      }
    ],
    "overview": "Assigns one or more attribute values to an Item. Existing equal mappings are idempotent; set attributes[].overwrite to true or use Inventory.Attribute.Update to change an existing value.",
    "notes": "Attribute values are typed according to the definition. Set createValueIfMissing on an attribute object when an Option value may need to be created. Blocked items require allowBlocked."
  },
  "conventions": "## Errors and warnings\r\nAn error response has `status` = `Error`, a stable `code`, the `error` text and, when they apply, `parameter` (the request parameter concerned, e.g. `lines[2].no`), `received` (the value received), `expected` (what was expected) and `nextStep` (what to do now). `hint` says where to read more.\r\nWhen a request has several problems, all of them are listed in `errors[]` - each with the same fields - under a top-level `code` (`MultipleErrors`, or a shared code such as `InvalidLine` for the `lines` of a Create type) and a summary `error`. Fix them all before calling again. One problem is reported at the top level, with no `errors[]`.\r\nRequest values are checked first and every problem found is reported together. A Business Central validation error raised afterwards, while a record is being written, stops the call and is reported on its own: `code` = `BusinessCentralError`, Business Central's own `error` text, and `parameter` naming the request parameter being applied, e.g. `lines[1].accountNo`. Nothing is written.\r\nRequest values are read in one format, whatever the language: dates `YYYY-MM-DD`; date-times ISO 8601 with `Z` or an offset; amounts as JSON numbers (or a string such as `\"1234.56\"`, no thousands separator); integers as JSON integers; booleans `true` or `false`. Any other value is `InvalidParameterFormat` with `received` and `expected`; for an unambiguous local form such as `26.09.2026`, `nextStep` gives the value to resend. Every bad value of a request is reported together.\r\nAnswers are written in one format as well, whatever the language of the call: dates `YYYY-MM-DD`, date-times ISO 8601, numbers with a dot and no thousands separator, and the option and enum values of every answer except `Data.Records.Get` and `Data.Records.Set` as their English names, so a value read from an answer can be sent back. Those two answer the caption of the language of the call, for a person to read. The language of the call (`lcid`) changes captions and message texts, not these forms. Two things are outside Bifrost's control: Business Central writes its own texts (a ledger entry description such as `Direct Cost V00010 on 10/02/26`, the text of a `BusinessCentralError`) with the regional settings of the server session, which `lcid` does not change, so a date in such a text can be in month-day order; and a table view is read with those settings too, so write dates in a view as `YYYY-MM-DD` and decimals with a dot.\r\nBoth success and error responses can carry `warnings[]`, each with `code`, `message` and, when they apply, `parameter` and `nextStep`.\r\n`UnknownParameter` refuses undeclared data keys before execution for every type whose effect is not read, including a missing effect. The root envelope option `strict:false` cannot opt out. Read types keep warnings without changing status, validationResult or domain warningCount unless the caller sets `strict:true` (next to type and subject, never inside data). Refusals list the keys and localized nextStep corrections; no business changes or successful execution charges occur. Example: {\"type\":\"Memory.User.Set\",\"strict\":true,\"data\":{\"memory\":\"test\",\"memry\":\"typo\"}} is refused.\r\n`FieldChangedByBC` is a warning from Data.Records.Set: another field validation or the write changed a sent field after its own validation. `parameter` names data[n].fields.{jsonName}, counting from 0. Status stays Success. Compare the returned values with what you sent; follow `nextStep` to use validation order or send the field again in a separate call. Normalisation of the field itself, LCY, Dimension Set ID, BLOB, Media, MediaSet and skipped fields are excluded.\r\nViðbætur (Foundation 28.0.8 eða nýrri) geta kallað á `Argument.SetErrorContext(Parameter, Expected, NextStep)` fyrir aðgerð sem gæti mistekist eftir gagnaskrif og síðan `Argument.ClearErrorContext()` eftir að hún tekst. Gefðu upp heiti færibreytu og þýddan texta, aldrei gildi úr beiðni, skráarinnihald, aðgangsupplýsingar eða kallstafla. Foundation skilar þessu samhengi með upprunalegu `BusinessCentralError` eftir afturköllun, einnig við ómeðhöndlaðar verkefnisvillur; `RespondWithLastError()` notar það líka. Viðmótið grípur ekki villur, staðfestir ekki gagnaskrif og breytir ekki færslumörkum. Haltu `Codeunit.Run` án skilagildis og láttu villur berast áfram þegar `OmitCommit` köll eru keðjuð; bættu aldrei við Boolean `Codeunit.Run` eða `TryFunction` sem skrifar gögn til að endurheimta samhengi. Samhengið er hreinsað milli skilaboða. Kallendur án samhengis halda óbreyttri uppbyggingu svars; þekktar læsingarvillur halda núverandi `Retryable` leiðbeiningum.\r\nSkilaboðagerð sem má aðeins keyra eftir einni leið (Foundation 28.0.9 eða nýrri) les `Argument.GetInvocationSource()`: `Queue` þegar verkraðari keyrir skilaboð sem biðraðarviðmótið setti í röð, `Task` fyrir verkviðmótið (`/tasks`), `Dispatcher` fyrir innra kall í gegnum `Dispatcher ori` (innbyggða MCP-verkfæraþjóninn, hreiðrað kall úr annarri skilaboðagerð) og `Direct` fyrir aðgerðina Keyra vinnslu á síðunni Skilaboð og allt sem ekki er skráð. Aðeins Foundation skráir gildið; gildi í beiðni, færibreytur, uppruni, efni og skrif í færibreytuna breyta því ekki. Hafnaðu öðrum leiðum með `PreconditionFailed` og `nextStep` sem nefnir leiðina sem á að nota.\r\n`Retryable` means a transient lock or deadlock caught while writing or posting. `error` keeps Business Central's original text. `expected` is \"no concurrent lock on the same records\"; `nextStep` is \"Retry the same call after a few seconds; nothing was changed.\" Bifrost does not retry automatically. Other platform errors, including uncaught queue-path errors, remain `BusinessCentralError`.\r\nCodes: `MissingParameter`, `InvalidParameterFormat`, `InvalidParameter`, `RecordNotFound`, `AmbiguousRecord`, `ConflictingIdentifiers`, `InvalidFilterField`, `InvalidLine`, `NothingToPreview`, `LinesSkipped`, `BlockedByWriteGuard`, `PreconditionFailed`, `PermissionDenied`, `LimitExceeded`, `BusinessCentralError`, `MultipleErrors`, `DeprecatedParameter`, `UnknownParameter`, `FieldChangedByBC`, `Retryable`, `EULA_REQUIRED`, `TRIAL_NOT_STARTED`. The `error` text may be translated; the code never is.\r\n"
}
